"""Playback tracking event composition handler."""

from __future__ import annotations

from typing import Any, ClassVar, Dict, List, Optional

import structlog

from rasa.core.channels.conversation_queue.queue import ConversationQueue
from rasa.core.channels.voice_stream.call_state import call_state
from rasa.core.channels.voice_stream.channel_controller.channel_controller import (
    ChannelCommand,
    ChannelController,
)
from rasa.core.voice.event_composition.events import CompositeEvent
from rasa.core.voice.event_composition.events.constants import (
    BOT_TEXT_METADATA_KEY,
    INTERRUPTED_WORD_INDEX_METADATA_KEY,
    INTERRUPTED_WORD_METADATA_KEY,
    RESPONSE_EVENT_ID_METADATA_KEY,
    RESPONSE_WORD_COUNT_METADATA_KEY,
    TOTAL_AUDIO_DURATION_MS_METADATA_KEY,
)
from rasa.core.voice.event_composition.events.input_events import (
    BotPlaybackInputEvent,
    BotPlaybackStartedInputEvent,
    BotPlaybackStoppedInputEvent,
    MarkerType,
    PlaybackMarkerAcknowledgedInputEvent,
    PlaybackMarkerSentInputEvent,
)
from rasa.core.voice.event_composition.handlers.protocol import (
    RawEventTypes,
)
from rasa.shared.core.playback_marker import (
    ACKNOWLEDGED_INTERMEDIATE_MARKERS_METADATA_KEY,
    BARGE_IN_PLAYBACK_METADATA_KEY,
    PlaybackMarkers,
    PlaybackPosition,
)

structlogger = structlog.get_logger()


class PlaybackTrackingHandler:
    """Track bot audio playback and publish its active state.

    Marker-based channels send a playback marker for each chunk of bot audio and echo
    back an acknowledgement once the client reaches it.

    Native playback channels report playback start and stop directly.

    This handler derives the shared ``CallState.is_bot_audio_active`` state from both
    mechanisms, so the rest of Rasa knows whether the response still has audio in
    flight.

    Attributes:
        _interaction_event_queue: The queue of composed events consumed by the
            processor. Reserved for future composite events; this handler currently
            only writes ``CallState`` playback state.
        _channel_controller: Channel-provided controller used to actuate channel
            actions (e.g. hanging up once playback finishes).
        _audio_markers: Sent markers not yet acknowledged, keyed by marker id.
        _hangup_triggered: True once we've asked the channel to hang up, so a
            later drain edge can't ask again (see the ack branch for why).
    """

    interested_in: ClassVar[RawEventTypes] = [
        PlaybackMarkerSentInputEvent,
        PlaybackMarkerAcknowledgedInputEvent,
        BotPlaybackStartedInputEvent,
        BotPlaybackStoppedInputEvent,
    ]

    def __init__(
        self,
        interaction_event_queue: ConversationQueue[CompositeEvent],
        channel_controller: Optional[ChannelController] = None,
    ) -> None:
        """Create a playback tracking handler."""
        self._interaction_event_queue = interaction_event_queue
        self._channel_controller = channel_controller
        self._audio_markers: Dict[str, PlaybackMarkerSentInputEvent] = {}
        self._marker_utterances: Dict[str, int] = {}
        self._utterance_audio_durations_ms: Dict[int, int] = {}
        self._utterance_bot_texts: Dict[int, str] = {}
        # Kept until the utterance's END marker is acknowledged.
        self._response_event_ids: Dict[int, str] = {}
        self._acknowledged_intermediate_markers: List[PlaybackPosition] = []
        self._next_utterance_number = 0
        self._sent_utterance_number: Optional[int] = None
        self._playing_utterance_number: Optional[int] = None
        self._playing_audio_duration_ms: Optional[int] = None
        self._playing_bot_text: Optional[str] = None
        self._hangup_triggered = False

    async def handle(self, event: BotPlaybackInputEvent) -> None:
        """Update playback state on the shared call state for one event."""
        # Old playback reports must not re-enable audio while output is suppressed.
        if call_state.user_has_floor:
            return None

        # Handle native playback events - there are no markers to derive this from.
        if isinstance(event, BotPlaybackStartedInputEvent):
            call_state.is_bot_audio_active = True
            return None
        if isinstance(event, BotPlaybackStoppedInputEvent):
            call_state.is_bot_audio_active = False
            return None

        # Handle marker-based playback events
        if isinstance(event, PlaybackMarkerSentInputEvent):
            self._handle_playback_marker(event)
        elif isinstance(event, PlaybackMarkerAcknowledgedInputEvent):
            await self._handle_playback_marker_ack(event)
        return None

    def clear_playback_state(self) -> None:
        """Drop pending markers and clear bot playback state.

        Wired as a synchronous barge-in hook so the interrupted reply's markers are
        gone before any later event in the same raw batch, meaning a stale ack can no
        longer re-enable speaking.
        """
        structlogger.debug(
            "playback_tracking_handler.playback_state.cleared",
            conversation_id=self._interaction_event_queue.conversation_id,
            prior_pending_marker_count=len(self._audio_markers),
            was_bot_audio_active=call_state.is_bot_audio_active,
        )
        self._audio_markers.clear()
        self._marker_utterances.clear()
        self._utterance_audio_durations_ms.clear()
        self._utterance_bot_texts.clear()
        self._response_event_ids.clear()
        self._acknowledged_intermediate_markers.clear()
        self._sent_utterance_number = None
        self._playing_utterance_number = None
        self._playing_audio_duration_ms = None
        self._playing_bot_text = None
        call_state.is_bot_audio_active = False

    def _handle_playback_marker(self, event: PlaybackMarkerSentInputEvent) -> None:
        """Track a sent marker as pending bot audio until the client acks it.

        Every marker (start, intermediate, end) is a beacon in a bot audio chunk sent
        to the client and counts as pending audio; sending does not mean the client is
        playing it yet (that is decided on ack).
        """
        self._audio_markers[event.marker_id] = event
        if event.marker_type == MarkerType.START:
            self._next_utterance_number += 1
            self._sent_utterance_number = self._next_utterance_number
            metadata = event.metadata or {}
            response_event_id = metadata.get(RESPONSE_EVENT_ID_METADATA_KEY)
            if isinstance(response_event_id, str):
                self._response_event_ids[self._sent_utterance_number] = (
                    response_event_id
                )
            total_audio_duration_ms = metadata.get(TOTAL_AUDIO_DURATION_MS_METADATA_KEY)
            if isinstance(total_audio_duration_ms, int) and not isinstance(
                total_audio_duration_ms, bool
            ):
                self._utterance_audio_durations_ms[self._sent_utterance_number] = (
                    total_audio_duration_ms
                )
        if self._sent_utterance_number is not None:
            self._marker_utterances[event.marker_id] = self._sent_utterance_number
            self._record_bot_text(event, self._sent_utterance_number)
        self._update_audio_activity()

    def _record_bot_text(
        self, event: PlaybackMarkerSentInputEvent, utterance_number: int
    ) -> None:
        """Keep the latest text of an utterance from any of its sent markers.

        Streamed utterances only know their text as it is generated, so later
        markers carry more of it than the start marker.
        """
        bot_text = (event.metadata or {}).get(BOT_TEXT_METADATA_KEY)
        if not isinstance(bot_text, str):
            return
        if utterance_number == self._playing_utterance_number:
            self._playing_bot_text = bot_text
        else:
            self._utterance_bot_texts[utterance_number] = bot_text

    def _update_audio_activity(self) -> None:
        """Derive active audio from unacknowledged and currently playing markers."""
        call_state.is_bot_audio_active = bool(
            self._audio_markers or self._playing_utterance_number is not None
        )

    def get_barge_in_metadata(self) -> Optional[Dict[str, Any]]:
        """Return the acknowledged marker context for an interrupted utterance.

        Names the earliest response that has not finished playing, started or not.
        """
        response_event_id = next(iter(self._response_event_ids.values()), None)
        if (
            not self._acknowledged_intermediate_markers
            and self._playing_audio_duration_ms is None
            and response_event_id is None
        ):
            return None
        playback_metadata: Dict[str, Any] = {}
        if response_event_id is not None:
            playback_metadata[RESPONSE_EVENT_ID_METADATA_KEY] = response_event_id
        if self._acknowledged_intermediate_markers:
            playback_metadata[ACKNOWLEDGED_INTERMEDIATE_MARKERS_METADATA_KEY] = [
                position.as_metadata()
                for position in self._acknowledged_intermediate_markers
            ]
        if self._playing_audio_duration_ms is not None:
            playback_metadata[TOTAL_AUDIO_DURATION_MS_METADATA_KEY] = (
                self._playing_audio_duration_ms
            )
        playback_metadata.update(self._interrupted_word_metadata())
        return {BARGE_IN_PLAYBACK_METADATA_KEY: playback_metadata}

    def _interrupted_word_metadata(self) -> Dict[str, Any]:
        """Read the interrupted word from the playing reply at the marker index."""
        if self._playing_bot_text is None:
            return {}
        word_index = PlaybackMarkers(
            markers=list(self._acknowledged_intermediate_markers)
        ).confirmed_word_index()
        tokens = self._playing_bot_text.split()
        if word_index is None or word_index >= len(tokens):
            return {}
        return {
            INTERRUPTED_WORD_METADATA_KEY: tokens[word_index],
            INTERRUPTED_WORD_INDEX_METADATA_KEY: word_index,
            RESPONSE_WORD_COUNT_METADATA_KEY: len(tokens),
        }

    def get_playing_bot_text(self) -> Optional[str]:
        """Return the text of the utterance the client is currently playing.

        Set when the client acks an utterance's START marker, updated as later
        markers of that utterance bring more streamed text, and cleared when the
        client acks its END marker or a barge-in clears playback state.

        Returns:
            The playing utterance's latest text, or ``None`` when nothing is
            playing, no marker carried text yet (the first second of a streamed
            response), or the channel reports playback natively.
        """
        return self._playing_bot_text

    async def _handle_playback_marker_ack(
        self, event: PlaybackMarkerAcknowledgedInputEvent
    ) -> None:
        """Handle a client ack: update playback state and hang up on drain.

        The client echoes the marker back once it has played that chunk, so an ack is
        what tells us the audio actually reached the user. A START ack means the client
        began playing this utterance; an END ack means it finished. Intermediate acks
        only clear their pending entry.
        """
        pending_before = len(self._audio_markers)
        acked_marker = self._audio_markers.pop(event.marker_id, None)
        marker_utterance = self._marker_utterances.pop(event.marker_id, None)

        if acked_marker is None:
            structlogger.debug(
                "playback_tracking_handler.marker.ack.unmatched",
                conversation_id=self._interaction_event_queue.conversation_id,
                marker_id=event.marker_id,
                pending_marker_count=len(self._audio_markers),
            )
        elif acked_marker.marker_type == MarkerType.START:
            self._playing_utterance_number = marker_utterance
            self._playing_audio_duration_ms = (
                self._utterance_audio_durations_ms.get(marker_utterance)
                if marker_utterance is not None
                else None
            )
            self._playing_bot_text = (
                self._utterance_bot_texts.pop(marker_utterance, None)
                if marker_utterance is not None
                else None
            )
            self._acknowledged_intermediate_markers.clear()
            structlogger.debug(
                "playback_tracking_handler.speaking.started",
                conversation_id=self._interaction_event_queue.conversation_id,
                marker_id=event.marker_id,
                pending_marker_count=len(self._audio_markers),
            )
        elif acked_marker.marker_type == MarkerType.END:
            self._response_event_ids.pop(marker_utterance, None)
            is_playing_utterance = (
                marker_utterance is not None
                and marker_utterance == self._playing_utterance_number
            )
            structlogger.debug(
                "playback_tracking_handler.speaking.stopped",
                conversation_id=self._interaction_event_queue.conversation_id,
                marker_id=event.marker_id,
                pending_marker_count=len(self._audio_markers),
            )

            if is_playing_utterance:
                # A naturally completed utterance has no tracker event to enrich.
                self._acknowledged_intermediate_markers.clear()
                self._playing_utterance_number = None
                self._playing_audio_duration_ms = None
                self._playing_bot_text = None
        elif (
            acked_marker.marker_type == MarkerType.INTERMEDIATE
            and marker_utterance is not None
            and marker_utterance == self._playing_utterance_number
        ):
            if acked_marker.position is not None:
                self._acknowledged_intermediate_markers.append(acked_marker.position)
            structlogger.debug(
                "playback_tracking_handler.intermediate_marker.acknowledged",
                conversation_id=self._interaction_event_queue.conversation_id,
                marker_id=event.marker_id,
                position=(
                    acked_marker.position.as_metadata()
                    if acked_marker.position is not None
                    else None
                ),
            )

        self._update_audio_activity()

        # Drain edge: playback just finished. Hang up only on this natural drain
        # (non-empty -> empty), and only once; a multi-message goodbye can drain more
        # than once, but we want a single hangup after the final message finishes.
        if (
            pending_before > 0
            and len(self._audio_markers) == 0
            and call_state.hangup_requested
            and not self._hangup_triggered
            and self._channel_controller is not None
        ):
            self._hangup_triggered = True
            structlogger.debug("playback_tracking_handler.hangup.trigger")
            await self._channel_controller.invoke(ChannelCommand.HANGUP)
